from functools import wraps

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @wraps(func)
        def wrapper(session, *args, **kwargs):
            return session.write_transaction(lambda tx: func(tx, *args, **kwargs), metadata=metadata, timeout=timeout)
        return wrapper
    return decorator

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f'{key} is not in the list')

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self._record.values())
    else:
        return [self._record[key] for key in keys if key in self._record]

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    all_keys = list(self.__dict__.keys())

    if not keys:
        return dict(self.__dict__)

    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(all_keys):
                raise IndexError("Index out of bounds")
            result[all_keys[key]] = self.__dict__.get(all_keys[key], None)
        elif isinstance(key, str):
            result[key] = self.__dict__.get(key, None)
        else:
            raise TypeError("Keys must be integers or strings")

    return result

import struct

class DataStream:
    def __init__(self, data):
        self.data = data

    def pop_u16(self):
        """ Remove the last two bytes of data, returning them as a big-endian
        16-bit unsigned integer.
        """
        if len(self.data) < 2:
            raise ValueError("Not enough data to pop a 16-bit integer")
        value = struct.unpack('>H', self.data[-2:])[0]
        self.data = self.data[:-2]
        return value

