def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimal = []

    def add_bases(cls):
        if cls not in seen:
            seen.add(cls)
            for base in cls.__bases__:
                add_bases(base)
            minimal.append(cls)

    for cls in classes:
        add_bases(cls)

    minimal.reverse()
    return minimal

