def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}

    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict):
            sub_diff = difference(d1[key], d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff
        elif d1[key] != d2[key]:
            diff[key] = d1[key]

    return diff

import re
from typing import Dict, List, Any, Union

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[Union[str, Any], str]]):
        self.messages = messages
        super().__init__(f"Validation errors: {self.messages}")

def _validate_labels(labels: Dict[str, Any]):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression.
    """
    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_\-\.]+$')
    errors = []

    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        elif not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex '^[a-zA-Z0-9_]+$'"})

        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
                elif not value_regex.match(item):
                    errors.append({item: f"Label value '{item}' does not match the regex '^[a-zA-Z0-9_\-\.]+$'"})
        elif not isinstance(value, str):
            errors.append({str(value): 'expected string or bytes-like object'})
        elif not value_regex.match(value):
            errors.append({value: f"Label value '{value}' does not match the regex '^[a-zA-Z0-9_\-\.]+$'"})

    if errors:
        raise ValidationError(errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present
    """
    for schema_item, response_item in zip(observer_schema, response):
        if isinstance(schema_item, dict) and isinstance(response_item, dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest, schema_item, response_item
            )
        elif isinstance(schema_item, list) and isinstance(response_item, list):
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest, schema_item, response_item
            )
        else:
            if len(last_applied_manifest) < len(response):
                last_applied_manifest.append(None)
            if last_applied_manifest[len(response) - 1] is None:
                last_applied_manifest[len(response) - 1] = response_item
def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, schema_value in observer_schema.items():
        if key in response:
            response_value = response[key]
            if isinstance(schema_value, dict) and isinstance(response_value, dict):
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema_value, response_value
                )
            elif isinstance(schema_value, list) and isinstance(response_value, list):
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = []
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], schema_value, response_value
                )
            elif key not in last_applied_manifest:
                last_applied_manifest[key] = response_value

from krake.data.kubernetes import Application

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schema = {}
    for resource_type, manifest in app.spec.manifest.items():
        if resource_type not in app.spec.observer_schema:
            # Generate a default observer schema for the resource type
            default_schema[resource_type] = {
                "status": {
                    "type": "object",
                    "properties": {
                        "conditions": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "type": {"type": "string"},
                                    "status": {"type": "string"},
                                    "lastProbeTime": {"type": "string"},
                                    "lastTransitionTime": {"type": "string"},
                                    "reason": {"type": "string"},
                                    "message": {"type": "string"}
                                },
                                "required": ["type", "status"]
                            }
                        }
                    }
                }
            }
    return default_schema

from typing import AnyStr, Union, Iterable, Dict, Sequence, Tuple, List
import re

class SQLParams:
    def __init__(self, in_style: str, out_style: str):
        self.in_style = in_style
        self.out_style = out_style

class SQLFormatter:
    def __init__(self, sql_params: SQLParams):
        self.sql_params = sql_params

    def formatmany(
        self,
        sql: AnyStr,
        many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
    ) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
        if self.sql_params.in_style == 'named' and self.sql_params.out_style == 'qmark':
            return self._format_named_to_qmark(sql, many_params)
        elif self.sql_params.in_style == 'pyformat' and self.sql_params.out_style == 'qmark':
            return self._format_pyformat_to_qmark(sql, many_params)
        # Add more style conversions as needed
        raise ValueError("Unsupported parameter style conversion")

    def _format_named_to_qmark(self, sql: AnyStr, many_params: Iterable[Dict[Union[str, int], Any]]):
        placeholders = re.findall(r':(\w+)', sql)
        new_sql = re.sub(r':(\w+)', '?', sql)
        new_params = [[param[placeholder] for placeholder in placeholders] for param in many_params]
        return new_sql, new_params

    def _format_pyformat_to_qmark(self, sql: AnyStr, many_params: Iterable[Dict[Union[str, int], Any]]):
        placeholders = re.findall(r'%\((\w+)\)', sql)
        new_sql = re.sub(r'%\(\w+\)', '?', sql)
        new_params = [[param[placeholder] for placeholder in placeholders] for param in many_params]
        return new_sql, new_params

