class InventoryValidator:
    def __init__(self, spec_version):
        self.spec_version = spec_version

    def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if extract_spec_version:
            type_value = inventory.get('type')
            if isinstance(type_value, str) and type_value.startswith('v'):
                try:
                    version = int(type_value[1:])
                    self.spec_version = version
                except ValueError:
                    pass

        # Placeholder for additional validation logic
        if self.spec_version == 1:
            return self._validate_v1(inventory)
        elif self.spec_version == 2:
            return self._validate_v2(inventory)
        else:
            raise ValueError(f"Unsupported spec version: {self.spec_version}")

    def _validate_v1(self, inventory):
        # Example validation for version 1
        required_keys = {'id', 'name', 'quantity'}
        if not required_keys.issubset(inventory.keys()):
            raise ValueError("Inventory is missing required keys for version 1")
        return inventory

    def _validate_v2(self, inventory):
