class ExpressionAbsorber:
    def __init__(self):
        pass

    def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        from sympy import And, Or, Not, simplify

        def apply_absorption(expr):
            if isinstance(expr, And):
                a, b = expr.args
                if isinstance(b, Or) and a in b.args:
                    return a
                if isinstance(b, Or) and Not(a) in b.args:
                    return And(a, b.args[1] if b.args[0] == Not(a) else b.args[0])
            elif isinstance(expr, Or):
                a, b = expr.args
                if isinstance(b, And) and a in b.args:
                    return a
                if isinstance(b, And) and Not(a) in b.args:
                    return Or(a, b.args[1] if b.args[0] == Not(a) else b.args[0])
            return expr

        return [simplify(apply_absorption(arg)) for arg in args]

