from ruamel.yaml.nodes import ScalarNode, MappingNode

def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_into(target, source):
        if isinstance(source, MappingNode) and isinstance(target, MappingNode):
            target_map = {key.as_string(): value for key, value in target.value}
            source_map = {key.as_string(): value for key, value in source.value}
            for key_str, source_value in source_map.items():
                if key_str in target_map:
                    target_map[key_str] = merge_into(target_map[key_str], source_value)
                else:
                    target_map[key_str] = source_value
            target.value = [(ScalarNode(tag='tag:yaml.org,2002:str', value=key), value) for key, value in target_map.items()]
        else:
            return source
        return target

    merged = defaultdict(lambda: (None, None))
    for key_node, value_node in nodes:
        key_str = key_node.as_string()
        if merged[key_str][0] is not None:
            merge_into(merged[key_str][1], value_node)
        else:
            merged[key_str] = (key_node, value_node)

    return list(merged.values())

