import logging
import json
import os

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                     msg=f"Configuration file not found: {filename}", args=(), exc_info=None)
            log_records.append(record)
            continue

        try:
            with open(filename, 'r') as file:
                config = json.load(file)
            config_dict[filename] = config
        except json.JSONDecodeError as e:
            record = logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0,
                                     msg=f"Error parsing configuration file {filename}: {e}", args=(), exc_info=True)
            log_records.append(record)

    if overrides:
        for key, value in overrides.items():
            if key in config_dict:
                config_dict[key].update(value)
            else:
                config_dict[key] = value

    if resolve_env:
        for filename, config in config_dict.items():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('$'):
                    env_var = value[1:]
                    config[key] = os.getenv(env_var, value)

    return config_dict, log_records

