from collections import OrderedDict, defaultdict

class LFUCache:
    def __init__(self):
        self.freq = defaultdict(OrderedDict)
        self.keys = {}
        self.min_freq = 0

    def popitem(self):
        """Remove and return the `(key, value)` pair least frequently used."""
        if not self.keys:
            raise KeyError('LFUCache is empty')
        key, value = self.freq[self.min_freq].popitem(last=False)
        del self.keys[key]
        if not self.freq[self.min_freq]:
            del self.freq[self.min_freq]
        return key, value

