def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try parsing as JSON
        data = json.loads(document)
        return {
            "hcard_url": next((link['href'] for link in data.get('links', []) if link.get('rel') == 'http://microformats.org/profile/hcard'), None),
            "alias": data.get('subject')
        }
    except json.JSONDecodeError:
        # Fallback to parsing as XRD
        try:
            root = ET.fromstring(document)
            xrd_ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
            hcard_url = root.find(".//xrd:Link[@rel='http://microformats.org/profile/hcard']", xrd_ns)
            alias = root.find(".//xrd:Subject", xrd_ns)
            return {
                "hcard_url": hcard_url.get('href') if hcard_url is not None else None,
                "alias": alias.text if alias is not None else None
            }
        except ET.ParseError:
            return {}

