import warnings

class DeprecatedArgsMixin:
    def get_deprecated_args(self):
        """Returning dict with options which deprecate others."""
        deprecated_args = {
            "old_option1": "new_option1",
            "old_option2": "new_option2"
        }
        return deprecated_args

    def __init__(self, **kwargs):
        self._check_deprecated_args(kwargs)

    def _check_deprecated_args(self, kwargs):
        deprecated_args = self.get_deprecated_args()
        for old_arg, new_arg in deprecated_args.items():
            if old_arg in kwargs:
                warnings.warn(
                    f"Argument '{old_arg}' has been deprecated in favor of '{new_arg}'. "
                    f"'{old_arg}' will be removed in a future version.",
                    category=DeprecationWarning,
                    stacklevel=2
                )
                kwargs[new_arg] = kwargs.pop(old_arg)
        return kwargs

