        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        parser_func = self.parsers.get(command_name)
        if parser_func:
            parser = argparse.ArgumentParser(description=f"Options for {command_name}")
            parser_func(parser)
            return parser
        else:
            raise ValueError(f"No options defined for command: {command_name}")

