        args = parser_instance.parse_args(['--verbose', '--config', '/etc/config.yaml'])
        print(args)
    except ValueError as e:
        print(e)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    if command_name in self.options:
        if argument_name in self.options[command_name]:
            return self.options[command_name][argument_name]
    return None

class Validator:
    def validate_length_args(self, args):
        """Check if value of arguments is not longer than length specified.

        :param args: The received arguments.
        """
        for arg in args:
            value = arg.get('value')
            length = arg.get('length')
            if value is not None and length is not None:
                if len(value) > length:
                    raise ValueError(f"Value '{value}' exceeds specified length of {length}")

# Example usage
if __name__ == "__main__":
    validator = Validator()
    args = [
        {'value': 'hello', 'length': 10},
        {'value': 'worldwide', 'length': 5}
    ]
    try:
        validator.validate_length_args(args)
    except ValueError as e:
        print(e)

class ArgumentValidator:
    def __init__(self, choices):
        self.choices = choices

    def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        for arg_name, value in args.items():
            if arg_name in self.choices and value not in self.choices[arg_name]:
                raise ValueError(f"Invalid value for {arg_name}: {value}. Must be one of {self.choices[arg_name]}")

# Example usage
if __name__ == "__main__":
    validator = ArgumentValidator({
        'color': ['red', 'green', 'blue'],
        'size': ['small', 'medium', 'large']
    })

    try:
        validator.validate_choices_args({'color': 'red', 'size': 'medium'})
        print("Arguments are valid.")
    except ValueError as e:
        print(e)

    try:
        validator.validate_choices_args({'color': 'yellow', 'size': 'medium'})
    except ValueError as e:
        print(e)

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments, expected to be a list of tuples (value, min, max).
    :raise ValueError: When any value is not between its corresponding min and max.
    """
    for value, min_val, max_val in args:
        if not (min_val <= value <= max_val):
            raise ValueError(f"Value {value} is not between {min_val} and {max_val}")

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []

    for extra_var in extra_vars:
        if isinstance(extra_var, dict):
            vars_dict.update(extra_var)
        elif isinstance(extra_var, str):
            key, value = extra_var.split('=', 1)
            vars_dict[key] = value
    return vars_dict

import os
import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    if not os.path.exists(spec_path):
        return {}

    with open(spec_path, 'r') as f:
        spec_data = json.load(f)

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec_data)

